            $MJTC_logo = esc_url(MJTC_PLUGIN_URL)."includes/images/aboutus_page/logo.png";
            $MJTC_query = "INSERT INTO `" . majesticsupport::$_db->prefix . "mjtc_support_emailtemplates` (`id`, `templatefor`, `title`, `subject`, `body`, `created`, `status`) VALUES
                                (1, 'ticket-new', '', '{SITETITLE}: New Ticket Received', '<div style=\"margin: 0; padding: 0; background-color: #cbd5e1; font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, \'Helvetica Neue\', Arial, sans-serif; -webkit-font-smoothing: antialiased;\"><table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"background-color: #cbd5e1; padding: 50px 15px;\"><tr><td align=\"center\"><table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width: 680px; background-color: #ffffff; border-radius: 8px; box-shadow: 0 15px 35px rgba(15, 23, 42, 0.15); overflow: hidden; border: 1px solid #94a3b8;\"><tr><td style=\"background-color: #1e293b; padding: 30px 40px;\"><table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\"><tr><td align=\"left\" valign=\"middle\" style=\"color:#ffffff;\"><img src=\"$MJTC_logo\" alt=\"{SITETITLE}\" style=\"max-height: 45px; border: none; display: block;\" /></td><td align=\"right\" valign=\"middle\"><div style=\"background-color: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); padding: 8px 16px; border-radius: 6px;\"><span style=\"font-size: 12px; font-weight: 700; color: #e2e8f0; text-transform: uppercase; letter-spacing: 1px;\">Ticket Control Center</span></div></td></tr></table></td></tr><tr><td style=\"background-color: #392c7d; padding: 40px; border-bottom: 4px solid #818cf8;\"><table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\"><tr><td valign=\"middle\"><span style=\"display: inline-block; font-size: 12px; font-weight: 700; color: #a5b4fc; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px;\">{SITETITLE} - New Ticket Received</span><h1 style=\"margin: 0; font-size: 28px; font-weight: 800; color: #ffffff; letter-spacing: -0.5px;\">Ticket Submitted Successfully</h1></td></tr></table></td></tr><tr><td style=\"padding: 40px; background-color: #f8fafc; border-bottom: 1px solid #cbd5e